USE pet_adoption_network;
DROP TRIGGER IF EXISTS trg_medical_followup_alert; DROP TRIGGER IF EXISTS trg_adoption_status_sync; DROP TRIGGER IF EXISTS trg_foster_capacity_insert; DROP TRIGGER IF EXISTS trg_foster_capacity_update;
DELIMITER $$
CREATE TRIGGER trg_medical_followup_alert AFTER INSERT ON medical_records FOR EACH ROW BEGIN IF NEW.next_checkup_date IS NOT NULL AND NEW.next_checkup_date<CURRENT_DATE AND NEW.follow_up_status='Pending' THEN INSERT IGNORE INTO medical_followup_alerts(medical_id,remarks) VALUES(NEW.medical_id,'Automatically generated overdue alert'); END IF; END$$
CREATE TRIGGER trg_adoption_status_sync AFTER INSERT ON adoption_records FOR EACH ROW BEGIN IF NEW.adoption_status='Completed' THEN UPDATE animals SET current_status='Adopted' WHERE animal_id=NEW.animal_id; END IF; END$$
CREATE TRIGGER trg_foster_capacity_insert BEFORE INSERT ON fostering FOR EACH ROW BEGIN DECLARE c INT; DECLARE m INT; SELECT maximum_capacity INTO m FROM foster_homes WHERE foster_id=NEW.foster_id FOR UPDATE; SELECT COUNT(*) INTO c FROM fostering WHERE foster_id=NEW.foster_id AND foster_status='Active'; IF NEW.foster_status='Active' AND c>=m THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Foster home capacity exceeded'; END IF; IF NEW.foster_status='Active' THEN UPDATE animals SET current_status='Fostered' WHERE animal_id=NEW.animal_id; END IF; END$$
CREATE TRIGGER trg_foster_capacity_update BEFORE UPDATE ON fostering FOR EACH ROW BEGIN DECLARE c INT; DECLARE m INT; IF NEW.foster_status='Active' AND OLD.foster_status<>'Active' THEN SELECT maximum_capacity INTO m FROM foster_homes WHERE foster_id=NEW.foster_id FOR UPDATE; SELECT COUNT(*) INTO c FROM fostering WHERE foster_id=NEW.foster_id AND foster_status='Active' AND foster_record_id<>OLD.foster_record_id; IF c>=m THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Foster home capacity exceeded'; END IF; END IF; IF OLD.foster_status='Active' AND NEW.foster_status='Completed' THEN UPDATE animals SET current_status='Available' WHERE animal_id=NEW.animal_id; END IF; END$$
DELIMITER ;
